--
-- Table structure for table `md_bank_account`
--

DROP TABLE IF EXISTS `md_bank_account`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `md_bank_account` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `tenant_id` bigint NOT NULL COMMENT '租户ID【多租户隔离字段】',
  `company_id` bigint NOT NULL COMMENT '所属公司ID',
  `account_code` varchar(64) NOT NULL COMMENT '账户编码',
  `account_name` varchar(200) NOT NULL COMMENT '账户名称',
  `bank_name` varchar(200) NOT NULL COMMENT '开户银行',
  `bank_branch` varchar(200) DEFAULT NULL COMMENT '开户支行',
  `bank_account` varchar(64) NOT NULL COMMENT '银行账号',
  `bank_code` varchar(64) DEFAULT NULL COMMENT '联行号',
  `account_type` varchar(20) DEFAULT 'BANK',
  `currency_code` varchar(10) NOT NULL DEFAULT 'CNY' COMMENT '币种',
  `balance` decimal(20,2) DEFAULT '0.00' COMMENT '账面余额(参考值)',
  `subject_id` bigint DEFAULT NULL COMMENT '对应银行存款科目ID',
  `is_default` tinyint NOT NULL DEFAULT '0' COMMENT '是否默认付款账户',
  `status` varchar(20) NOT NULL DEFAULT 'NORMAL' COMMENT '状态:NORMAL/DISABLED',
  `remark` varchar(500) DEFAULT NULL,
  `create_by` bigint DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint DEFAULT NULL,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tenant_account_code` (`tenant_id`,`account_code`),
  KEY `idx_tenant` (`tenant_id`),
  KEY `idx_tenant_company` (`tenant_id`,`company_id`)
) ENGINE=InnoDB AUTO_INCREMENT=247 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='公司付款账户';
/*!40101 SET character_set_client = @saved_cs_client */;

